const body = $input.first().json.body || $input.first().json;

if (!body.prompt) {
  throw new Error('Request body must include a "prompt" field describing the app to generate.');
}

const targetTypes = {
  static: 'static website (plain HTML, CSS, and vanilla JavaScript only - no frameworks, no npm, no build step)',
  frontend: 'frontend (React, single-page app, no build step required to inspect the code)',
  backend: 'backend (Node.js + Express REST API)'
};
const target = targetTypes[body.target] ? body.target : 'backend';
const targetType = targetTypes[target];

const projectRules = target === 'static'
  ? `- The site MUST work by opening index.html directly in a browser (file://): no server, no package.json, no CDN or external requests; reference CSS/JS/images with relative paths.
- Put the entry page at index.html; split styles into .css files and scripts into .js files.
- Use only images you can express inline (SVG or CSS); do not reference image files you don't include.`
  : `- Include every file needed to run the project (source code, package.json, a README with run instructions).
- For a backend project, package.json MUST include a "start" script that boots the server, and the server MUST listen on process.env.PORT (falling back to 3000 if unset) — this is required for automated deployment.`;

const outputDir = (body.outputDir || 'generated-app').replace(/[^a-zA-Z0-9_-]/g, '-');

const systemPrompt = `You are a code generator. Given a plain-language description of an app, output a complete, runnable ${targetType} project as STRICT JSON only, matching exactly this schema and nothing else (no markdown fences, no commentary, no text before or after the JSON):

{"files":[{"path":"relative/file/path.ext","content":"full file contents as a string"}]}

Rules:
${projectRules}
- Keep the project minimal but functional — favor completeness over cleverness.
- Do not include node_modules, .git, or any build output.
- All "path" values must be relative (no leading slash, no "..").
- Respond with the JSON object only.`;

return [{
  json: {
    systemPrompt,
    userPrompt: body.prompt,
    outputDir
  }
}];

const response = $input.first().json;
// OpenAI-style chat completion (Gemini's compatibility endpoint). Anthropic Messages
// responses are still understood, so switching providers back only touches Call Gemini.
const choice = (response.choices || [])[0] || {};
const text = choice.message
  ? String(choice.message.content || '')
  : (response.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const truncated = choice.finish_reason === 'length' || response.stop_reason === 'max_tokens';
const jsonText = text.trim().replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');

const safePathRe = /^[A-Za-z0-9_][A-Za-z0-9_.\-\/]*$/;
const isSafePath = p => typeof p === 'string' && safePathRe.test(p) && p.indexOf('..') === -1;

if (truncated) {
  throw new Error('The model hit the max_tokens limit before finishing the JSON. Ask for a smaller app, or raise max_tokens in the Call Gemini node.');
}

let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (e) {
  throw new Error('The model did not return valid JSON. Raw response (truncated): ' + text.slice(0, 500));
}

if (!parsed.files || !Array.isArray(parsed.files)) {
  throw new Error('Expected a "files" array in the generated JSON but did not find one.');
}

const bad = parsed.files.find(f => !isSafePath(f.path));
if (bad) {
  throw new Error('Unsafe or invalid file path from generated output: ' + JSON.stringify(bad.path));
}

const outputDir = $('Prepare Prompt').first().json.outputDir;

return parsed.files.map(f => ({
  json: {
    path: f.path,
    content: f.content,
    outputDir
  }
}));

const items = $input.all();
const files = items.map(i => i.json.path);

return [{
  json: {
    status: 'ok',
    outputDir: items[0] ? items[0].json.outputDir : null,
    filesWritten: files.length,
    files
  }
}];
